111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        normalizeAddress(ownerFieldsDto);
115	        validateRequiredFields(ownerFieldsDto);
116	        normalizeTelephone(ownerFieldsDto);
117	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
118	        rejectDuplicateHousehold(ownerFieldsDto);
119	        normalizeEmail(ownerFieldsDto);
120	        defaultRegistrationDate(ownerFieldsDto);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        assignCustomerCode(owner);
124	        assignHouseholdId(owner);
125	        assignNamesakeCount(owner);
126	        assignMembershipNumber(owner);
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
