216	    /**
217	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
218	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
219	     * Validation already rejects {@code null} values and the pattern-constrained fields
220	     * when blank, but {@code address} and {@code city} have no pattern, so a
221	     * whitespace-only value would otherwise slip through.
222	     *
223	     * @param ownerFieldsDto the submitted owner fields
224	     * @throws RequiredFieldsMissingException if any required field is missing or blank
225	     */
226	    /**
227	     * Common street-type abbreviations expanded during address normalization. Keys are the
228	     * upper-cased abbreviation tokens; values are their canonical expansions.
229	     */
230	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
231	        "ST", "STREET",
232	        "RD", "ROAD",
233	        "AVE", "AVENUE");
234	
235	    /**
236	     * Normalizes the submitted address on create and writes the canonical value back onto the
237	     * request so it is persisted, echoed back, and used for every downstream address comparison
238	     * (household duplicate detection and the household id). The value is trimmed, internal
239	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
240	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
241	     * {@code null} address is left untouched so the required-field check can report it as missing.
242	     *
243	     * @param ownerFieldsDto the submitted owner fields
244	     */
245	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
246	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
247	    }
248	
249	    /**
250	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
251	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
252	     * expanded to its full form. A {@code null} value is returned unchanged.
253	     *
254	     * @param raw the address to canonicalize, possibly {@code null}
255	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
256	     */
257	    private static String normalizeAddress(String raw) {
258	        if (raw == null) {
259	            return null;
260	        }
261	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
262	        if (collapsed.isEmpty()) {
263	            return collapsed;
264	        }
265	        String[] tokens = collapsed.split(" ");
266	        StringBuilder sb = new StringBuilder(collapsed.length());
267	        for (int i = 0; i < tokens.length; i++) {
268	            if (i > 0) {
269	                sb.append(' ');
270	            }
271	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
272	        }
273	        return sb.toString();
274	    }
275	
276	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
277	        List<String> errors = new ArrayList<>();
278	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
279	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
280	        requireText("address", ownerFieldsDto.getAddress(), errors);
281	        requireText("city", ownerFieldsDto.getCity(), errors);
282	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
283	        if (!errors.isEmpty()) {
284	            throw new RequiredFieldsMissingException(errors);
285	        }
286	    }
287	
288	    private static void requireText(String field, String value, List<String> errors) {
289	        if (value == null || value.isBlank()) {
290	            errors.add(field);
291	        }
292	    }
293	
294	    /**
295	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
296	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
297	     * and echoed back in that form.
298	     *
299	     * @param ownerFieldsDto the submitted owner fields
300	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
301	     *                                        valid E.164 number
302	     */
303	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
304	        String e164 = toE164(ownerFieldsDto.getTelephone());
305	        if (e164 == null) {
306	            throw new RequiredFieldsMissingException(List.of("telephone"));
307	        }
308	        ownerFieldsDto.setTelephone(e164);
309	    }
310	
311	    /**
312	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
313	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
314	     * and country code are present they are kept; otherwise country code {@code '+61'} is
315	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
316	     * must contain 8 to 15 digits after the {@code '+'}.
317	     *
318	     * @param raw the submitted telephone, possibly {@code null}
319	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
320	     */
321	    private static String toE164(String raw) {
322	        if (raw == null) {
323	            return null;
324	        }
325	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
326	        String digits;
327	        if (cleaned.startsWith("+")) {
328	            digits = cleaned.substring(1);
329	        } else {
330	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
331	            digits = "61" + national;
332	        }
333	        if (!digits.matches("[0-9]{8,15}")) {
334	            return null;
335	        }
336	        return "+" + digits;
337	    }
338	
339	    /**
340	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
341	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
342	     * each stored owner's telephone is normalized the same way before comparison so differing
343	     * input formats collapse to the same value.
344	     *
345	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
346	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
347	     *                                     same E.164 telephone
348	     */
349	    /**
350	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
351	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
352	     * the parts may contain whitespace or a second {@code @}.
353	     */
354	    private static final Pattern EMAIL_PATTERN =
355	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
356	
357	    /**
358	     * Normalizes the submitted email when present: the value is trimmed, required to be a
359	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
360	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
361	     *
362	     * @param ownerFieldsDto the submitted owner fields
363	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
364	     */
365	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
366	        String email = ownerFieldsDto.getEmail();
367	        if (email == null) {
368	            return;
369	        }
370	        String trimmed = email.strip();
371	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
372	            throw new InvalidEmailException(email);
373	        }
374	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
375	    }
376	
377	    /**
378	     * Defaults the registration date on create: when the client does not supply a
379	     * {@code registrationDate}, it is set to the server's current date so it is persisted
380	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
381	     *
382	     * @param ownerFieldsDto the submitted owner fields
383	     */
384	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
385	        if (ownerFieldsDto.getRegistrationDate() == null) {
386	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
387	        }
388	    }
389	
390	    /**
391	     * Assigns the owner's {@code customerCode} on create, formatted
392	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
393	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
394	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
395	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
396	     *
397	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
398	     */
399	    private void assignCustomerCode(Owner owner) {
400	        String city = owner.getCity();
401	        String lastName = owner.getLastName();
402	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
403	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
404	        long sequence = this.clinicService.findAllOwners().stream()
405	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
406	            .count() + 1;
407	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
408	    }
409	
410	    /**
411	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
412	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
413	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
414	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
415	     * canonicalized fields, every owner in the same household — including one joining an existing
416	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
417	     * order.
418	     *
419	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
420	     */
421	    private void assignHouseholdId(Owner owner) {
422	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
423	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
424	    }
425	
426	    /**
427	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
428	     * already share this owner's {@code firstName} and {@code lastName}, compared
429	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
430	     * pre-existing namesakes.
431	     *
432	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
433	     */
434	    private void assignNamesakeCount(Owner owner) {
435	        String firstName = owner.getFirstName();
436	        String lastName = owner.getLastName();
437	        long count = this.clinicService.findAllOwners().stream()
438	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
439	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
440	            .count();
441	        owner.setNamesakeCount((int) count);
442	    }
443	
444	    /**
445	     * Assigns the owner's {@code membershipNumber} on create, formatted
446	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
447	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
448	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
449	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
450	     *
451	     * @param owner the owner being created (with its {@code customerCode} and
452	     *              {@code registrationDate} already set)
453	     */
454	    private void assignMembershipNumber(Owner owner) {
455	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
456	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
457	    }
458	
459	    /**
460	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
461	     *
462	     * @param value the string to hash
463	     * @return the 64-character lower-case hex digest
464	     */
465	    private static String sha256Hex(String value) {
466	        try {
467	            byte[] digest = MessageDigest.getInstance("SHA-256")
468	                .digest(value.getBytes(StandardCharsets.UTF_8));
469	            StringBuilder sb = new StringBuilder(digest.length * 2);
470	            for (byte b : digest) {
471	                sb.append(String.format("%02x", b));
472	            }
473	            return sb.toString();
474	        }
475	        catch (NoSuchAlgorithmException e) {
476	            throw new IllegalStateException("SHA-256 not available", e);
477	        }
478	    }
479	
480	    private void rejectDuplicateTelephone(String normalizedTelephone) {
481	        boolean duplicate = this.clinicService.findAllOwners().stream()
482	            .map(Owner::getTelephone)
483	            .map(OwnerRestControllerV1::toE164)
484	            .filter(telephone -> telephone != null)
485	            .anyMatch(normalizedTelephone::equals);
486	        if (duplicate) {
487	            throw new DuplicateTelephoneException(normalizedTelephone);
488	        }
489	    }
490	
491	    /**
492	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
493	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
494	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
495	     * still counts as the same household. The check is skipped when the request opts in via
496	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
497	     * the existing one.
498	     *
499	     * @param ownerFieldsDto the submitted owner fields
500	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
501	     *                                     last name and address and the request did not opt in
502	     */
503	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
504	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
505	            return;
506	        }
507	        String lastName = collapse(ownerFieldsDto.getLastName());
508	        String address = collapse(ownerFieldsDto.getAddress());
509	        boolean duplicate = this.clinicService.findAllOwners().stream()
510	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
511	                && collapse(owner.getAddress()).equals(address));
512	        if (duplicate) {
513	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
514	        }
515	    }
516	
517	    /**
518	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
519	     * every internal run of whitespace is collapsed to a single space, and the result is
520	     * lower-cased. A {@code null} value collapses to the empty string.
521	     *
522	     * @param value the value to canonicalize, possibly {@code null}
523	     * @return the collapsed, lower-cased value
524	     */
525	    private static String collapse(String value) {
526	        if (value == null) {
527	            return "";
528	        }
529	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
530	    }
